  refresh_token: account.refresh_token,
  // Don't set access_token, force a refresh
});

// Force token refresh
try {
  const newTokens = await oauth2Client.refreshAccessToken();
  console.log('Refreshed token scopes:', newTokens.credentials.scope);
  console.log('Token type:', newTokens.credentials.token_type);
  console.log('Token (first 30):', newTokens.credentials.access_token?.substring(0, 30));

