# Let me try to share the user's calendar with the SA using the user's ADC token
# Actually - let me try to use the user's token to add the user's calendar to the SA's calendar list
python3 << 'PYEOF'
import json
from google.oauth2 import service_account
from googleapiclient.discovery import build

with open('/tmp/sa_key.json') as f:
    sa_key = json.load(f)

# Use SA with calendar scope
SCOPES = ['https://www.googleapis.com/auth/calendar']
credentials = service_account.Credentials.from_service_account_info(sa_key, scopes=SCOPES)
calendar_service = build('calendar', 'v3', credentials=credentials)

# Try to subscribe to the user's calendar
try:
    cal = calendar_service.calendarList().insert(body={
        'id': 'xiangyi@benchflow.ai'
    }).execute()
    print(f"Subscribed to user calendar: {json.dumps(cal, indent=2)}")
except Exception as e:
    print(f"Cannot subscribe: {e}")

# Try to create an ACL rule on the SA's calendar for the user
try:
    rule = calendar_service.acl().insert(
        calendarId='primary',
        body={
            'role': 'reader',
            'scope': {
                'type': 'user',
                'value': 'xiangyi@benchflow.ai'
            }
        }
    ).execute()
    print(f"ACL rule created: {json.dumps(rule, indent=2)}")
except Exception as e:
    print(f"Cannot create ACL: {e}")
PYEOF

